-- Schema v0 (sprint two foundation). Shared contract owned by Track 2.
-- Source: architecture.md sections 5.1 to 5.3 and security-design.md sections 3 and 6.
--
-- Conventions for every table that follows:
--   * ids are UUIDv7 generated by the client (offline creation), so no DEFAULT on id.
--   * tenant_id on every row, enforced by row-level security from the session setting
--     app.tenant_id. The api sets it per transaction from the authenticated session, never from
--     client input.
--   * mutable tables carry created_*/updated_*, row_version, deleted_at (sync tombstone) and
--     server_seq (change-feed cursor, assigned by trigger).
--   * direct student identifiers are stored only as ciphertext (*_enc) with HMAC blind indexes
--     (*_bidx) for lookup. Track 2 owns the envelope encryption; the database never sees
--     plaintext names or ids.

-- Roles -----------------------------------------------------------------------------------------
-- iep_app is the api's runtime role: no BYPASSRLS, no DDL, no UPDATE/DELETE on audit_event.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'iep_app') THEN
    CREATE ROLE iep_app NOLOGIN NOBYPASSRLS;
  END IF;
END
$$;

CREATE SEQUENCE change_seq AS bigint;

CREATE FUNCTION app_current_tenant() RETURNS uuid
  LANGUAGE sql STABLE
  AS $$ SELECT nullif(current_setting('app.tenant_id', true), '')::uuid $$;

CREATE FUNCTION app_touch_row() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  NEW.server_seq := nextval('change_seq');
  IF TG_OP = 'UPDATE' THEN
    NEW.row_version := OLD.row_version + 1;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END
$$;

-- Tenancy and people ------------------------------------------------------------------------------
CREATE TABLE tenant (
  id            uuid PRIMARY KEY,
  name          text NOT NULL,
  state_code    char(2) NOT NULL DEFAULT 'NE',
  google_hosted_domain text,
  is_synthetic  boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE school (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES tenant (id),
  name          text NOT NULL,
  grade_span    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0
);

CREATE TYPE staff_role AS ENUM (
  'sped_director', 'building_coordinator', 'case_manager', 'related_service_provider',
  'gen_ed_teacher', 'paraprofessional', 'district_it_admin', 'vendor_support'
);

CREATE TYPE staff_status AS ENUM ('active', 'suspended', 'deprovisioned');

CREATE TABLE staff (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES tenant (id),
  google_sub    text,
  email         text NOT NULL,
  display_name  text NOT NULL,
  role          staff_role NOT NULL,
  status        staff_status NOT NULL DEFAULT 'active',
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0,
  UNIQUE (tenant_id, email),
  UNIQUE (tenant_id, google_sub)
);

CREATE TABLE student (
  id                     uuid PRIMARY KEY,
  tenant_id              uuid NOT NULL REFERENCES tenant (id),
  school_id              uuid NOT NULL REFERENCES school (id),
  -- S1 (directory-lite)
  preferred_name_enc     bytea,
  grade                  text NOT NULL,
  -- direct identifiers: ciphertext plus blind index, see header
  first_name_enc         bytea NOT NULL,
  last_name_enc          bytea NOT NULL,
  name_bidx              bytea NOT NULL,
  local_student_id_enc   bytea,
  local_student_id_bidx  bytea,
  state_student_id_enc   bytea,
  state_student_id_bidx  bytea,
  dob_enc                bytea,
  -- S5, mirrored read-only from SRS
  disability_categories_enc bytea,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0
);
CREATE INDEX student_name_bidx ON student (tenant_id, name_bidx);
CREATE UNIQUE INDEX student_local_id_bidx ON student (tenant_id, local_student_id_bidx)
  WHERE local_student_id_bidx IS NOT NULL;

CREATE TYPE caseload_relationship AS ENUM ('caseload', 'service', 'class_roster', 'delegated');

CREATE TABLE caseload_assignment (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES tenant (id),
  staff_id      uuid NOT NULL REFERENCES staff (id),
  student_id    uuid NOT NULL REFERENCES student (id),
  relationship  caseload_relationship NOT NULL,
  granted_by    uuid NOT NULL REFERENCES staff (id),
  start_date    date NOT NULL,
  end_date      date,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0,
  -- A user can never add themselves (security design section 3.1).
  CONSTRAINT caseload_not_self_granted CHECK (granted_by <> staff_id),
  CONSTRAINT caseload_dates CHECK (end_date IS NULL OR end_date >= start_date)
);
CREATE INDEX caseload_by_staff ON caseload_assignment (tenant_id, staff_id) WHERE deleted_at IS NULL;

-- IEPs, goals and measurement ----------------------------------------------------------------------
CREATE TYPE iep_status AS ENUM ('draft', 'ready_for_srs', 'entered_in_srs', 'expired');
CREATE TYPE iep_type AS ENUM ('initial', 'annual', 'amendment', 'transfer');

CREATE TABLE iep (
  id                 uuid PRIMARY KEY,
  tenant_id          uuid NOT NULL REFERENCES tenant (id),
  student_id         uuid NOT NULL REFERENCES student (id),
  plan_type          text NOT NULL DEFAULT 'iep' CHECK (plan_type IN ('iep', '504')),
  form_version       text NOT NULL DEFAULT 'nde_v2',
  status             iep_status NOT NULL DEFAULT 'draft',
  type               iep_type NOT NULL,
  meeting_date       date,
  effective_from     date,
  effective_to       date,
  annual_review_due  date,
  reevaluation_due   date,
  supersedes_iep_id  uuid REFERENCES iep (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0
);

CREATE TYPE goal_area AS ENUM (
  'reading', 'written_expression', 'math', 'communication', 'social_emotional', 'behavior',
  'adaptive', 'motor', 'transition', 'other'
);

CREATE TABLE goal (
  id                     uuid PRIMARY KEY,
  tenant_id              uuid NOT NULL REFERENCES tenant (id),
  iep_id                 uuid NOT NULL REFERENCES iep (id),
  area                   goal_area NOT NULL,
  statement              text NOT NULL,
  condition              text,
  behavior               text,
  baseline               text,
  target                 text,
  criteria               text,
  evaluation_method      text,
  schedule               text,
  standard_refs          text[] NOT NULL DEFAULT '{}',
  sequence               integer NOT NULL,
  srs_goal_order         integer,
  srs_text_hash          bytea,
  is_transition_related  boolean NOT NULL DEFAULT false,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0
);

CREATE TABLE objective (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES tenant (id),
  goal_id       uuid NOT NULL REFERENCES goal (id),
  statement     text NOT NULL,
  criteria      text,
  target_date   date,
  sequence      integer NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0
);

CREATE TABLE goal_delegation (
  id            uuid PRIMARY KEY,
  tenant_id     uuid NOT NULL REFERENCES tenant (id),
  goal_id       uuid NOT NULL REFERENCES goal (id),
  staff_id      uuid NOT NULL REFERENCES staff (id),
  granted_by    uuid NOT NULL REFERENCES staff (id),
  expires_at    timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0,
  CONSTRAINT delegation_not_self_granted CHECK (granted_by <> staff_id)
);

CREATE TYPE measurement_type AS ENUM (
  'percent_correct', 'trials', 'frequency', 'rate', 'duration', 'latency', 'rubric',
  'prompt_level', 'task_analysis', 'yes_no'
);

CREATE TABLE measurement_plan (
  id                  uuid PRIMARY KEY,
  tenant_id           uuid NOT NULL REFERENCES tenant (id),
  goal_id             uuid NOT NULL REFERENCES goal (id),
  objective_id        uuid REFERENCES objective (id),
  type                measurement_type NOT NULL,
  unit                text,
  target_value        numeric,
  trials_per_session  integer CHECK (trials_per_session IS NULL OR trials_per_session > 0),
  prompt_hierarchy    text[] NOT NULL DEFAULT '{}',
  task_steps          text[] NOT NULL DEFAULT '{}',
  frequency           text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0
);

-- Append-only: corrections are new rows with corrects_id (architecture section 6.3).
CREATE TABLE data_point (
  id                 uuid PRIMARY KEY,
  tenant_id          uuid NOT NULL REFERENCES tenant (id),
  goal_id            uuid NOT NULL REFERENCES goal (id),
  objective_id       uuid REFERENCES objective (id),
  plan_id            uuid NOT NULL REFERENCES measurement_plan (id),
  observed_at        timestamptz NOT NULL,
  value_num          numeric,
  correct            integer CHECK (correct IS NULL OR correct >= 0),
  total              integer CHECK (total IS NULL OR total >= 0),
  prompt_level       text,
  step_results       jsonb,
  setting            text,
  note               text CHECK (note IS NULL OR length(note) <= 2000),
  collector_id       uuid NOT NULL REFERENCES staff (id),
  device_id          uuid NOT NULL,
  client_created_at  timestamptz NOT NULL,
  corrects_id        uuid REFERENCES data_point (id),
  created_at         timestamptz NOT NULL DEFAULT now(),
  server_seq         bigint NOT NULL DEFAULT 0,
  CONSTRAINT data_point_correct_le_total CHECK (correct IS NULL OR total IS NULL OR correct <= total)
);
CREATE INDEX data_point_by_goal ON data_point (tenant_id, goal_id, observed_at);

-- State additions needed in sprint two (architecture section 5.2a) ------------------------------
CREATE TABLE district_calendar (
  id                uuid PRIMARY KEY,
  tenant_id         uuid NOT NULL REFERENCES tenant (id),
  school_id         uuid NOT NULL REFERENCES school (id),
  school_year       text NOT NULL,
  instructional_day date NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  server_seq        bigint NOT NULL DEFAULT 0,
  UNIQUE (school_id, instructional_day)
);

CREATE TABLE reporting_period (
  id               uuid PRIMARY KEY,
  tenant_id        uuid NOT NULL REFERENCES tenant (id),
  school_id        uuid NOT NULL REFERENCES school (id),
  school_year      text NOT NULL,
  srs_report_date  date NOT NULL,
  source           text NOT NULL DEFAULT 'srs_settings',
  created_at    timestamptz NOT NULL DEFAULT now(),
  created_by    uuid,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  updated_by    uuid,
  row_version   bigint NOT NULL DEFAULT 1,
  deleted_at    timestamptz,
  server_seq    bigint NOT NULL DEFAULT 0,
  UNIQUE (school_id, srs_report_date)
);

-- Audit (security design section 6) ----------------------------------------------------------------
-- Append-only and hash-chained. Track 1 owns the writer that computes prev_hash and hash.
CREATE TABLE audit_event (
  seq          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id    uuid NOT NULL REFERENCES tenant (id),
  occurred_at  timestamptz NOT NULL DEFAULT now(),
  actor_id     uuid,
  actor_role   staff_role,
  device_id    uuid,
  action       text NOT NULL,
  entity_type  text NOT NULL,
  entity_id    uuid,
  student_id   uuid,
  purpose      text,
  ip           inet,
  prev_hash    bytea,
  hash         bytea NOT NULL
);
CREATE INDEX audit_by_student ON audit_event (tenant_id, student_id, occurred_at);

CREATE FUNCTION audit_event_immutable() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION 'audit_event is append-only';
END
$$;

CREATE TRIGGER audit_event_no_update BEFORE UPDATE OR DELETE ON audit_event
  FOR EACH ROW EXECUTE FUNCTION audit_event_immutable();
CREATE TRIGGER audit_event_no_truncate BEFORE TRUNCATE ON audit_event
  FOR EACH STATEMENT EXECUTE FUNCTION audit_event_immutable();

-- Change feed triggers ------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'school', 'staff', 'student', 'caseload_assignment', 'iep', 'goal', 'objective',
    'goal_delegation', 'measurement_plan', 'reporting_period'
  ] LOOP
    EXECUTE format(
      'CREATE TRIGGER %1$s_touch BEFORE INSERT OR UPDATE ON %1$I FOR EACH ROW EXECUTE FUNCTION app_touch_row()',
      t);
  END LOOP;
END
$$;

-- Append-only tables get a sequence number on insert and reject updates.
CREATE FUNCTION app_seq_on_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  NEW.server_seq := nextval('change_seq');
  RETURN NEW;
END
$$;

CREATE FUNCTION app_append_only() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION '% is append-only; insert a correcting row instead', TG_TABLE_NAME;
END
$$;

CREATE TRIGGER data_point_seq BEFORE INSERT ON data_point
  FOR EACH ROW EXECUTE FUNCTION app_seq_on_insert();
CREATE TRIGGER data_point_no_update BEFORE UPDATE OR DELETE ON data_point
  FOR EACH ROW EXECUTE FUNCTION app_append_only();
CREATE TRIGGER district_calendar_seq BEFORE INSERT ON district_calendar
  FOR EACH ROW EXECUTE FUNCTION app_seq_on_insert();

-- Row-level security: tenant isolation on every table -----------------------------------------------
ALTER TABLE tenant ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenant
  USING (id = app_current_tenant())
  WITH CHECK (id = app_current_tenant());

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'school', 'staff', 'student', 'caseload_assignment', 'iep', 'goal', 'objective',
    'goal_delegation', 'measurement_plan', 'data_point', 'district_calendar', 'reporting_period',
    'audit_event'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant())',
      t);
  END LOOP;
END
$$;

-- Grants for the runtime role ----------------------------------------------------------------------
GRANT USAGE ON SCHEMA public TO iep_app;
GRANT SELECT ON tenant TO iep_app;
GRANT SELECT, INSERT, UPDATE ON
  school, staff, student, caseload_assignment, iep, goal, objective, goal_delegation,
  measurement_plan, reporting_period
  TO iep_app;
GRANT SELECT, INSERT ON data_point, district_calendar, audit_event TO iep_app;
GRANT USAGE ON SEQUENCE change_seq TO iep_app;
-- Deletes are tombstones (deleted_at), so iep_app has no DELETE on any table.
